#!/usr/bin/env bash
set -euo pipefail

# The raw MVBench dataset contains json/ and video/ directories. MVBench.tsv is
# generated by VLMEvalKit inside the local dataset snapshot cache, not shipped
# in the raw dataset. Cache OpenGVLab/MVBench locally before running this script.
MODEL="Qwen/Qwen2.5-VL-3B-Instruct"

CUDA_VISIBLE_DEVICES=0 \
HF_HUB_OFFLINE=1 \
LMUData="${HOME}/LMUData" \
MAX_PIXELS=1003520 \
VIDEO_MAX_PIXELS=50176 \
FPS_MAX_FRAMES=16 \
swift eval \
  --model "${MODEL}" \
  --infer_backend vllm \
  --eval_backend VLMEvalKit \
  --eval_dataset MVBench
